const $=s=>document.querySelector(s);const defaults={name:'Your name',role:'Independent creative',bio:'Thoughtful ideas, considered details.\nI like making things that feel simple.',about:'I’m drawn to the space where good ideas meet careful execution. This is a small collection of things I’ve made, things I’m exploring, and what comes next.',email:''};let profile={...defaults};let zones=['Asia/Dubai'];let format='24h';try{profile={...defaults,...JSON.parse(localStorage.getItem('quiet-profile')||'{}')};zones=JSON.parse(localStorage.getItem('quiet-zones')||'null')||zones;format=localStorage.getItem('quiet-format')||format}catch{}const visitor=Intl.DateTimeFormat().resolvedOptions().timeZone;if(!localStorage.getItem('quiet-zones')&&visitor!=='Asia/Dubai')zones.push(visitor);zones=zones.filter(z=>{try{new Intl.DateTimeFormat('en',{timeZone:z});return true}catch{return false}}).slice(0,5);if(!zones.length)zones=['Asia/Dubai'];
const glyphs={'0':['01110','10001','10011','10101','11001','10001','01110'],'1':['00100','01100','00100','00100','00100','00100','01110'],'2':['01110','10001','00001','00010','00100','01000','11111'],'3':['11110','00001','00001','01110','00001','00001','11110'],'4':['00010','00110','01010','10010','11111','00010','00010'],'5':['11111','10000','10000','11110','00001','00001','11110'],'6':['01110','10000','10000','11110','10001','10001','01110'],'7':['11111','00001','00010','00100','01000','01000','01000'],'8':['01110','10001','10001','01110','10001','10001','01110'],'9':['01110','10001','10001','01111','00001','00001','01110'],':':['00000','00100','00100','00000','00100','00100','00000']};
function drawMatrix(el,value){if(el.dataset.value===value)return;el.dataset.value=value;el.replaceChildren();for(const char of value){const g=document.createElement('span');g.className='glyph';for(const row of glyphs[char]||glyphs['0'])for(const bit of row){const dot=document.createElement('i');dot.className='pixel'+(bit==='1'?' on':'');g.append(dot)}el.append(g)}}
const names={'Asia/Kolkata':'India','America/Los_Angeles':'Los Angeles','America/New_York':'New York'};function city(z){return names[z]||z.split('/').pop().replaceAll('_',' ')}
function renderZones(){const root=$('#clocks');root.replaceChildren();zones.forEach((z,i)=>{const row=document.createElement('div');row.className='clock-row';const matrix=document.createElement('div');matrix.className='matrix';matrix.setAttribute('role','img');matrix.dataset.zone=z;const meta=document.createElement('div');const name=document.createElement('div');name.className='city-name';name.textContent=city(z).toUpperCase();const sub=document.createElement('div');sub.className='city-sub';sub.dataset.zone=z;meta.append(name,sub);const remove=document.createElement('button');remove.className='remove-zone';remove.textContent='×';remove.setAttribute('aria-label',`Remove ${city(z)}`);remove.onclick=()=>{if(zones.length===1)return toast('Keep at least one timezone.');zones.splice(i,1);saveZones();renderZones()};row.append(matrix,meta,remove);root.append(row)});$('#add-zone').disabled=zones.length>=5;$('#add-zone').style.opacity=zones.length>=5?'.4':'1';updateClock()}
function saveZones(){try{localStorage.setItem('quiet-zones',JSON.stringify(zones))}catch{}}
function updateClock(){const now=new Date();document.querySelectorAll('.matrix').forEach(el=>{const z=el.dataset.zone;const parts=new Intl.DateTimeFormat('en-GB',{timeZone:z,hour:'2-digit',minute:'2-digit',hour12:format==='12h',hourCycle:format==='24h'?'h23':undefined}).formatToParts(now);const time=parts.filter(p=>['hour','minute','literal'].includes(p.type)).map(p=>p.value).join('').trim();drawMatrix(el,time);el.setAttribute('aria-label',`${city(z)} ${time}`)});document.querySelectorAll('.city-sub').forEach(el=>{const z=el.dataset.zone;const date=new Intl.DateTimeFormat('en',{timeZone:z,weekday:'short',month:'short',day:'numeric'}).format(now);const daypart=format==='12h'?new Intl.DateTimeFormat('en',{timeZone:z,hour:'numeric',hour12:true}).formatToParts(now).find(p=>p.type==='dayPeriod').value:new Intl.DateTimeFormat('en',{timeZone:z,timeZoneName:'shortOffset'}).formatToParts(now).find(p=>p.type==='timeZoneName').value;el.textContent=`${date} · ${daypart}`});$('#format').textContent=format==='24h'?'24H':'12H';$('#format').setAttribute('aria-label',`Switch to ${format==='24h'?'12':'24'}-hour time`)}
$('#format').onclick=()=>{format=format==='24h'?'12h':'24h';try{localStorage.setItem('quiet-format',format)}catch{}updateClock()};$('#add-zone').onclick=()=>$('#zone-dialog').showModal();$('#zone-form').onsubmit=e=>{e.preventDefault();const z=$('#zone').value;if(zones.includes(z))return toast('That timezone is already on the board.');if(zones.length>=5)return toast('You can add up to five timezones.');zones.push(z);saveZones();renderZones();$('#zone-dialog').close()};
function applyProfile(){$('#name').textContent=profile.name;$('#footer-name').textContent=profile.name;$('#role').textContent=profile.role.toUpperCase();$('#bio').textContent=profile.bio;$('#about-text').textContent=profile.about;document.title=profile.name==='Your name'?'Quiet — Personal Portfolio':`${profile.name} — Portfolio`;$('#contact-link').href=profile.email?`mailto:${profile.email}`:'#contact';$('#contact-note').textContent=profile.email||'A good conversation is a good place to start.'}
function editProfile(){const f=$('#profile-form');Object.keys(defaults).forEach(k=>f.elements[k].value=profile[k]);$('#profile-dialog').showModal()};$('#personalize').onclick=editProfile;function contact(e){if(!profile.email){e.preventDefault();editProfile();toast('Add your email to enable contact.')}else if(e.currentTarget.id==='contact-button')location.href=`mailto:${profile.email}`};$('#contact-link').onclick=contact;$('#contact-button').onclick=contact;$('#profile-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);Object.keys(defaults).forEach(k=>profile[k]=String(data.get(k)||'').trim()||defaults[k]);try{localStorage.setItem('quiet-profile',JSON.stringify(profile))}catch{}applyProfile();$('#profile-dialog').close();toast('Your details are saved in this browser.')};
const projects=[['Form & feeling','A visual direction exploring the balance between geometric structure and a softer, more intuitive feel. Overlapping forms become a simple visual language.'],['Less, but considered','An exploration of typography, space, and hierarchy. A quiet interface that lets the essentials take the lead.'],['Everyday objects','A collection of small visual experiments. Repetition, texture, and familiar forms seen from a different angle.']];document.querySelectorAll('[data-project]').forEach(el=>el.onclick=()=>{const p=projects[Number(el.dataset.project)];$('#project-title').textContent=p[0];$('#project-description').textContent=p[1];$('#project-dialog').showModal()});document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));let toastTimer;function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}$('#year').textContent=new Date().getFullYear();applyProfile();renderZones();setInterval(updateClock,1000);
